/* Constant-current synchronous buck: the inductor current is compared with
   the reference once per sample (code.fs = 1 MHz) and the switch state is held
   inside a +/- band. S1 follows high, S2 its complement with dead time. */
const double band = 0.2;
if (current < reference - band) next_on = 1.0;
else if (current > reference + band) next_on = 0.0;
high = next_on;
